class ContractTemplate < DocumentTemplate
  belongs_to :account
  has_one :contract, dependent: :restrict_with_error

  validate :validate_if_contract_is_in_use, on: :destroy

  def validate_if_contract_is_in_use
    errors.add(:base, :being_used) if contract.present?
  end

  def self.create_default_templates(account)
    ApplicationRecord.connected_to(role: ActiveRecord.writing_role) do
      account.contract_templates.create!(name: 'Modelo Contrato de Prestação de Serviço (Diversos)',
                                         description: 'Modelo de contrato genérico para prestadores de serviços em geral',
                                         default: true,
                                         content: '<h3 class="min-h-[1rem] print:leading-7 print:min-h-[2rem] print:font-sans" style="text-align: center"><strong>CONTRATO DE PRESTAÇÃO DE SERVIÇOS</strong></h3><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7"></p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7"></p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7"><strong>CONTRATANTE</strong>: [NOME_CLIENTE], pessoa jurídica de direito privado, inscrita no CNPJ [CPF/CNPJ_CLIENTE], com sede na [ENDERECO_CLIENTE], nº. [NUMERO_ENDERECO_CLIENTE], no bairro [BAIRRO_ENDERECO_CLIENTE], no município de [CIDADE_ENDERECO_CLIENTE]-[ESTADO_ENDERECO_CLIENTE], CEP [CEP_ENDERECO_CLIENTE], por seu representante legal <input class="px-1 w-32 flex h-4 inline-flex rounded-md empty:bg-gray-100 mx-1 empty:placeholder-opacity-100 disabled:cursor-not-allowed placeholder:text-sm disabled:placeholder-opacity-100 empty:ring-1 ring-gray-300" placeholder="Preencher depois" disabled="true" id="input">, e-mail <input class="px-1 w-32 flex h-4 inline-flex rounded-md empty:bg-gray-100 mx-1 empty:placeholder-opacity-100 disabled:cursor-not-allowed placeholder:text-sm disabled:placeholder-opacity-100 empty:ring-1 ring-gray-300" placeholder="Preencher depois" disabled="true" id="input">.</p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7"></p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7"><strong>CONTRATADO(A)</strong>: [MINHA_EMPRESA], pessoa jurídica de direito privado, inscrita no CNPJ [MINHA_EMPRESA_CPF/CNPJ], com sede na [MINHA_EMPRESA_ENDERECO], nº.[MINHA_EMPRESA_NUMERO_ENDERECO], no bairro [MINHA_EMPRESA_BAIRRO], no município de [MINHA_EMPRESA_CIDADE]-[MINHA_EMPRESA_ESTADO], CEP [MINHA_EMPRESA_CEP], por seu representante legal <input class="px-1 w-32 flex h-4 inline-flex rounded-md empty:bg-gray-100 mx-1 empty:placeholder-opacity-100 disabled:cursor-not-allowed placeholder:text-sm disabled:placeholder-opacity-100 empty:ring-1 ring-gray-300" placeholder="Preencher depois" disabled="true" id="input">, e-mail <input class="px-1 w-32 flex h-4 inline-flex rounded-md empty:bg-gray-100 mx-1 empty:placeholder-opacity-100 disabled:cursor-not-allowed placeholder:text-sm disabled:placeholder-opacity-100 empty:ring-1 ring-gray-300" placeholder="Preencher depois" disabled="true" id="input">.</p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7"></p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7">As partes acima identificadas têm, entre si, justo e pactuado celebrar o presente <strong>CONTRATO DE PRESTAÇÃO DE SERVIÇOS</strong>, que reger-se-á mediante as cláusulas e condições adiante estipuladas.</p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7"></p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7"><strong>CLÁUSULA PRIMEIRA - DO OBJETO</strong></p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"></p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"><strong>1.1</strong> O presente contrato tem por objeto a prestação de serviços profissionais especializados em <input class="px-1 w-32 flex h-4 inline-flex rounded-md empty:bg-gray-100 mx-1 empty:placeholder-opacity-100 disabled:cursor-not-allowed placeholder:text-sm disabled:placeholder-opacity-100 empty:ring-1 ring-gray-300" placeholder="Preencher depois" disabled="true" id="input" style="text-align: justify"> por parte da CONTRATADA de acordo com os termos e condições detalhados neste contrato.</p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"></p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7"><strong>CLÁUSULA SEGUNDA - OBRIGAÇÕES DA CONTRATANTE</strong></p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"></p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"><strong>2.1 </strong>A CONTRATANTE deverá fornecer à CONTRATADA todas as informações necessárias à realização do serviço, devendo especificar os detalhes necessários à perfeita consecução do mesmo.</p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"><strong>2.2 </strong>A CONTRATANTE é obrigada ainda a disponibilizar: <input class="px-1 w-32 flex h-4 inline-flex rounded-md empty:bg-gray-100 mx-1 empty:placeholder-opacity-100 disabled:cursor-not-allowed placeholder:text-sm disabled:placeholder-opacity-100 empty:ring-1 ring-gray-300" placeholder="Preencher depois" disabled="true" id="input" style="text-align: justify"> (EPI’S ETC...)</p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"><strong>2.3</strong> A CONTRATANTE deverá efetuar o pagamento na forma e condições estabelecidas na cláusula quinta.</p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7"></p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7"><strong>CLÁUSULA TERCEIRA - OBRIGAÇÕES DA CONTRATADA</strong></p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"></p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"><strong>3.1</strong> A CONTRATADA deverá prestar os serviços solicitados pela CONTRATANTE conforme descritivo, especificações e prazos previstos no ANEXO I.</p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"><strong>3.2 </strong>A CONTRATADA se obriga a manter absoluto sigilo sobre as operações, dados, estratégias, materiais, informações e documentos da CONTRATANTE, mesmo após a conclusão dos serviços ou do término da relação contratual.</p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"><strong>3.3</strong> Os contratos, informações, dados, materiais e documentos inerentes à CONTRATANTE ou a seus clientes deverão ser utilizados, pela CONTRATADA, por seus funcionários ou contratados, estritamente para cumprimento dos serviços solicitados pela CONTRATANTE, sendo VEDADO a comercialização ou utilização para outros fins.</p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"><strong>3.4</strong> Será de responsabilidade da CONTRATADA todo o ônus trabalhista, tributário e previdenciário referente ao período que perdurar a prestação do serviço objeto deste instrumento, ficando a CONTRATANTE isenta de qualquer obrigação em relação a eles.</p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"><strong>3.5 </strong>A CONTRATADA deverá fornecer os respectivos documentos fiscais ou RPA’S (recibo de pagamento de autônomo), referente ao (s) pagamento (s) do presente instrumento.</p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"></p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7"><strong>CLÁUSULA QUARTA - DOS SERVIÇOS</strong></p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7"></p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"><strong>4.1</strong> A CONTRATADA atuará nos serviços contratados de acordo com as especificações descritas no ANEXO I, que passa ser parte integrante do presente contrato.</p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"><strong>4.2</strong> Os serviços terão início em <input class="px-1 w-32 flex h-4 inline-flex rounded-md empty:bg-gray-100 mx-1 empty:placeholder-opacity-100 disabled:cursor-not-allowed placeholder:text-sm disabled:placeholder-opacity-100 empty:ring-1 ring-gray-300" placeholder="Preencher depois" disabled="true" id="input"> dias corridos da assinatura do presente contrato.</p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"></p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7"><strong>CLÁUSULA QUINTA - DA AVALIAÇÃO DE PERFORMANCE</strong></p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"></p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"><strong>5.1 </strong>A execução dos serviços, objeto do presente contrato, passará por avaliações periódicas para fins de constatar o cumprimento dos indicadores de produtividade, abaixo indicados:</p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"><strong>5.1.1</strong> SEGURANÇA: Para fins de observância aos indicadores de segurança do presente contrato, mensalmente a CONTRATADA deve comprovar o uso regular de EPI’S ou quaisquer outros pedidos que tratem da segurança pessoal ou da regular prestação de serviço;</p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"><strong>5.1.2</strong> QUALIDADE: Para fins de observância aos indicadores de qualidade do presente contrato, mensalmente a CONTRATADA deve comprovar o cumprimento integral da prestação de serviço por meio de fotos ou qualquer outro meio estipulado pelo CONTRATANTE;</p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"><strong>5.1.3</strong> COMUNICAÇÃO: Para fins de observância aos indicadores de comunicação do presente contrato, mensalmente a CONTRATADA deve comprovar o uso eficiente dos materiais de comunicação (radio, celular etc..) ;</p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"><strong>5.1.4</strong> PONTUALIDADE: Para fins de observância aos indicadores de pontualidade do presente contrato, mensalmente a CONTRATADA deve comprovar o cumprimento integral do período mínimo fixado para desempenho da sua prestação de serviço;</p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"></p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7"><strong>CLÁUSULA SEXTA - DA EXCLUSIVIDADE</strong></p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"></p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"><strong>6.1 </strong>A CONTRATADA atuará <strong>COM EXCLUSIVIDADE</strong> em favor da CONTRATADA, NÃO podendo exercer sua atividade para outras empresas, ou efetuar negócios em nome e por conta própria, ainda que seja com terceiro não cliente da CONTRATANTE.</p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"><strong>6.2 </strong>A CONTRATADA terá gerência integral na área de serviço que lhe é destinada, com TOTAL AUTONOMIA, devendo atender exclusivamente o cronograma firmado entre as partes.</p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"></p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7"><strong>CLÁUSULA SÉTIMA - DO PREÇO E DAS CONDIÇÕES DE PAGAMENTO</strong></p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7"></p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"><strong>7.1 </strong>Os serviços OBJETO deste contrato serão remunerados pela quantia total de <input class="px-1 w-32 flex h-4 inline-flex rounded-md empty:bg-gray-100 mx-1 empty:placeholder-opacity-100 disabled:cursor-not-allowed placeholder:text-sm disabled:placeholder-opacity-100 empty:ring-1 ring-gray-300" placeholder="Preencher depois" disabled="true" id="input"> , a serem divididos em <input class="px-1 w-32 flex h-4 inline-flex rounded-md empty:bg-gray-100 mx-1 empty:placeholder-opacity-100 disabled:cursor-not-allowed placeholder:text-sm disabled:placeholder-opacity-100 empty:ring-1 ring-gray-300" placeholder="Preencher depois" disabled="true" id="input"> pagamentos, da seguinte forma:</p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify">1ª parcela: R$ <input class="px-1 w-32 flex h-4 inline-flex rounded-md empty:bg-gray-100 mx-1 empty:placeholder-opacity-100 disabled:cursor-not-allowed placeholder:text-sm disabled:placeholder-opacity-100 empty:ring-1 ring-gray-300" placeholder="Preencher depois" disabled="true" id="input"> (<input class="px-1 w-32 flex h-4 inline-flex rounded-md empty:bg-gray-100 mx-1 empty:placeholder-opacity-100 disabled:cursor-not-allowed placeholder:text-sm disabled:placeholder-opacity-100 empty:ring-1 ring-gray-300" placeholder="Preencher depois" disabled="true" id="input"> reais), a ser efetuado no dia <input class="px-1 w-32 flex h-4 inline-flex rounded-md empty:bg-gray-100 mx-1 empty:placeholder-opacity-100 disabled:cursor-not-allowed placeholder:text-sm disabled:placeholder-opacity-100 empty:ring-1 ring-gray-300" placeholder="Preencher depois" disabled="true" id="input">;</p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify">2ª parcela: R$ <input class="px-1 w-32 flex h-4 inline-flex rounded-md empty:bg-gray-100 mx-1 empty:placeholder-opacity-100 disabled:cursor-not-allowed placeholder:text-sm disabled:placeholder-opacity-100 empty:ring-1 ring-gray-300" placeholder="Preencher depois" disabled="true" id="input"> (<input class="px-1 w-32 flex h-4 inline-flex rounded-md empty:bg-gray-100 mx-1 empty:placeholder-opacity-100 disabled:cursor-not-allowed placeholder:text-sm disabled:placeholder-opacity-100 empty:ring-1 ring-gray-300" placeholder="Preencher depois" disabled="true" id="input"> reais), a ser efetuado no dia <input class="px-1 w-32 flex h-4 inline-flex rounded-md empty:bg-gray-100 mx-1 empty:placeholder-opacity-100 disabled:cursor-not-allowed placeholder:text-sm disabled:placeholder-opacity-100 empty:ring-1 ring-gray-300" placeholder="Preencher depois" disabled="true" id="input">;</p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify">3ª parcela: R$ <input class="px-1 w-32 flex h-4 inline-flex rounded-md empty:bg-gray-100 mx-1 empty:placeholder-opacity-100 disabled:cursor-not-allowed placeholder:text-sm disabled:placeholder-opacity-100 empty:ring-1 ring-gray-300" placeholder="Preencher depois" disabled="true" id="input"> (<input class="px-1 w-32 flex h-4 inline-flex rounded-md empty:bg-gray-100 mx-1 empty:placeholder-opacity-100 disabled:cursor-not-allowed placeholder:text-sm disabled:placeholder-opacity-100 empty:ring-1 ring-gray-300" placeholder="Preencher depois" disabled="true" id="input"> reais), a ser efetuado no dia <input class="px-1 w-32 flex h-4 inline-flex rounded-md empty:bg-gray-100 mx-1 empty:placeholder-opacity-100 disabled:cursor-not-allowed placeholder:text-sm disabled:placeholder-opacity-100 empty:ring-1 ring-gray-300" placeholder="Preencher depois" disabled="true" id="input">.</p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"><strong>7.2 </strong>No caso de atraso no pagamento superior a 10 dias, será devida multa moratória no valor de <input class="px-1 w-32 flex h-4 inline-flex rounded-md empty:bg-gray-100 mx-1 empty:placeholder-opacity-100 disabled:cursor-not-allowed placeholder:text-sm disabled:placeholder-opacity-100 empty:ring-1 ring-gray-300" placeholder="Preencher depois" disabled="true" id="input"> sobre a parcela inadimplida, além da atualização do valor pelo <input class="px-1 w-32 flex h-4 inline-flex rounded-md empty:bg-gray-100 mx-1 empty:placeholder-opacity-100 disabled:cursor-not-allowed placeholder:text-sm disabled:placeholder-opacity-100 empty:ring-1 ring-gray-300" placeholder="Preencher depois" disabled="true" id="input"> .</p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"><strong>7.3 </strong>Considera-se o cumprimento integral do contrato o momento em que todos os serviços especificados no ANEXO I tenham sido concluídos, mediante aprovação e revisão final da CONTRATANTE ou outra forma de entrega especificada no ANEXO I.</p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"></p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7"><strong>CLÁUSULA OITAVA - DO DESCUMPRIMENTO</strong></p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7"></p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"><strong>8.1 </strong>O descumprimento de qualquer uma das cláusulas por qualquer parte, implicará na rescisão imediata deste contrato, não isentando a CONTRATADA de suas responsabilidades referentes ao zelo com informações e dados da CONTRATANTE.</p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"></p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7"><strong>CLÁUSULA NONA - DO PRAZO E VALIDADE</strong></p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"></p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"><strong>9.1 </strong>A CONTRATADA deverá realizar os serviços dentro dos prazos determinados no cronograma previsto no ANEXO I, sendo sua responsabilidade comunicar a impossibilidade de cumprimento, bem como os motivos para tal e o novo prazo previsto, estando em sua competência a capacidade para tal avaliação.</p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"><strong>9.2 </strong>Este instrumento é válido pelo prazo de 1 ano, prorrogável por igual período, até a finalização do serviço, ora contratado, ou encerramento do contrato, não ficando as partes isentas de seus compromissos éticos.</p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"></p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7"><strong>CLÁUSULA DÉCIMA - DA RESCISÃO IMOTIVADA</strong></p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7"></p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"><strong>10.1 </strong>Poderá o presente instrumento ser rescindido por qualquer das partes, em qualquer momento, sem que haja qualquer tipo de motivo relevante, respeitando-se um período mínimo de <input class="px-1 w-32 flex h-4 inline-flex rounded-md empty:bg-gray-100 mx-1 empty:placeholder-opacity-100 disabled:cursor-not-allowed placeholder:text-sm disabled:placeholder-opacity-100 empty:ring-1 ring-gray-300" placeholder="Preencher depois" disabled="true" id="input"> dias, devendo então somente ser finalizadas e pagas as etapas que já estiverem em andamento.</p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"></p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7"><strong>CLÁUSULA DÉCIMA PRIMEIRA - DA OBSERVÂNCIA À LGPD</strong></p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7"></p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"><strong>11.1 </strong>O CONTRATANTE declara expresso CONSENTIMENTO que o CONTRATADO irá coletar, tratar e compartilhar os dados necessários ao cumprimento do contrato, nos termos do Art. 7º, inc. V da LGPD, os dados necessários para cumprimento de obrigações legais, nos termos do Art. 7º, inc. II da LGPD, bem como os dados, se necessários para proteção ao crédito, conforme autorizado pelo Art. 7º, inc. V da LGPD.</p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"><strong>11.2</strong> Outros dados poderão ser coletados, conforme termo de consentimento específico.</p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"></p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7"><strong>CLÁUSULA DÉCIMA SEGUNDA - DAS DISPOSIÇÕES GERAIS</strong></p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"></p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"><strong>12.1 </strong>Fica pactuada a total inexistência de vínculo trabalhista entre as partes, excluindo as obrigações previdenciárias e os encargos sociais, não havendo entre CONTRATADA e CONTRATANTE qualquer tipo de relação de subordinação.</p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"><strong>12.2</strong> A contratação da CONTRATADA, cumpridas todas as formalidades legais, com ou sem exclusividade, de forma contínua ou não, afasta a qualidade de empregado prevista no art. 3º da CLT, nos termos do art. 442-B da CLT.</p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"><strong>12.3</strong> A tolerância, por qualquer das partes, com relação ao descumprimento de qualquer termo ou condição aqui ajustado, não será considerada como desistência em exigir o cumprimento de disposição nele contida, nem representará novação com relação à obrigação passada, presente ou futura, no tocante ao termo ou condição cujo descumprimento foi tolerado.</p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"></p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7"><strong>CLÁUSULA DÉCIMA TERCEIRA - DO FORO</strong></p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"></p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"><strong>13.1 </strong>Para dirimir quaisquer controvérsias oriundas do presente contrato, as partes elegem o foro da Comarca de [MINHA_EMPRESA_CIDADE]&nbsp; do Estado de [MINHA_EMPRESA_ESTADO]&nbsp; .</p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify">Por estarem assim justos e de acordo, firmam o presente instrumento, em duas vias de igual teor, juntamente com 2 (duas) testemunhas.</p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"></p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify">[MINHA_EMPRESA_CIDADE]&nbsp;, [DATA_ATUAL]&nbsp;.</p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"></p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify">__________________________________________________</p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify">CONTRATANTE</p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"></p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify">__________________________________________________</p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify">CONTRATADO</p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"></p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"></p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"><strong>TESTEMUNHAS:</strong></p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"></p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify">____________________________________________________</p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify">CPF/MF:</p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"></p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify">____________________________________________________</p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify">CPF/MF:</p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"></p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"></p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"></p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"><em>---------------------------------- [Não imprimir abaixo] --------------------------------------</em></p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"></p><p class="min-h-[1rem] text-xs print:text-[1.35rem] print:min-h-[1.9rem] print:font-sans leading-4 print:leading-7" style="text-align: justify"><strong>ANEXO</strong></p>')
